    },
    { type: 'BookingStarted', bookingId: 'bk-1', occurredAt: '2026-08-05T09:00:00.000Z', actorId: 'u-pat', actualStartAt: '2026-08-05T09:00:00.000Z' },
    { type: 'BookingCompleted', bookingId: 'bk-1', occurredAt: '2026-08-05T13:05:00.000Z', actorId: 'u-pat', actualEndAt: '2026-08-05T13:05:00.000Z' },
  ] as DomainEvent[];
}

describe('REQ-41 GET /bookings/:bookingId/history', () => {
